p=argparse.ArgumentParser();p.add_argument('--recommend',required=True);opt=p.parse_args()
out=Path('media/new_lineage_audit_20261026');a=json.loads((out/'analysis.json').read_text());index=json.loads((out/'checkpoint_index.json').read_text());models=json.loads((out/'models.json').read_text())
def g(label,speed=.35):return next(x for x in a['groups'] if x['model']==label and x['speed']==speed)
